# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs, floor_=2):
    return [v for v in xs if v > floor_]

# region: fold
def fold(xs, factor=3):
    return [v * factor for v in xs]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: render
def render(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return render(emit(fold(intake(digest(shape(raw))))))

